import {calculate,combinePlan,validateData,MAX_QUANTITY,formatDuration,planDuration,calculateAvailable,SUBSTANCE_SECTIONS} from './core.js?v=4';
const $=s=>document.querySelector(s);
import {renderBusiness,configureBusiness} from './business.js?v=4';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n.toLocaleString('en-AU');
let guide,recipes=[],category='ammo',selectedId,quantity=60,plan=[],inventory={},editorTab='photos';
let smeltMode='available',availableAmount=0,availableItemId='';
let weaponTier=3;
let substanceSection='meth';
function renderSubstanceSections(){
  const host=$('#substance-sections');host.hidden=category!=='substances';
  if(host.hidden){host.innerHTML='';return;}
  host.innerHTML=`<p class="eyebrow">SUBSTANCE GUIDES</p><div class="tier-options substance-options" role="group" aria-label="Substance section">${Object.entries(SUBSTANCE_SECTIONS).map(([id,name])=>{const count=Object.values(guide.substanceGuides?.[id]||{}).some(value=>typeof value==='string'&&value.trim());return `<button data-substance="${id}" aria-pressed="${substanceSection===id}"><span>${name}</span><small>${Object.values(guide.substanceGuides?.[id]||{}).some(value=>typeof value==='string'&&value.trim())?'Read guide':'Details coming soon'}</small></button>`;}).join('')}</div>`;
  host.querySelectorAll('[data-substance]').forEach(b=>b.onclick=()=>{substanceSection=b.dataset.substance;selectedId=undefined;render();host.querySelector(`[data-substance="${substanceSection}"]`).focus();});
}
function renderWeaponTiers(){
  const host=$('#weapon-tiers');host.hidden=category!=='weapons';
  if(host.hidden){host.innerHTML='';return;}
  host.innerHTML=`<p class="eyebrow">WEAPON TIERS</p><div class="tier-options" role="group" aria-label="Weapon tier">${[1,2,3].map(t=>{const count=recipes.filter(r=>r.categoryId==='weapons'&&r.tier===t).length;return `<button data-tier="${t}" aria-pressed="${weaponTier===t}"><span>Tier ${t}</span><small>${count?count+' recipes':'Recipes coming soon'}</small></button>`;}).join('')}</div>`;
  host.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{weaponTier=Number(b.dataset.tier);selectedId=undefined;render();host.querySelector(`[data-tier="${weaponTier}"]`).focus();});
}
const substanceFields={overview:'Overview',requirements:'Before you start',locations:'Locations',steps:'Step-by-step guide',tips:'Tips & notes'};
function renderSubstanceGuide(){
  const entry=guide.substanceGuides?.[substanceSection]||{};
  $('#page-title').textContent='Substance guides';$('#breadcrumb').textContent='GUIDES';
  $('#page-description').textContent='Explore the in-city process, what to bring and where to go.';
  const section=(key)=>{const value=entry[key]||'';const lines=value.split('\n').map(s=>s.trim()).filter(Boolean);return `<section class="guide-chapter" id="substance-${key}"><h3>${substanceFields[key]}</h3>${lines.length?(key==='steps'?`<ol>${lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ol>`:key==='requirements'||key==='tips'?`<ul>${lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ul>`:lines.map(line=>`<p>${esc(line)}</p>`).join('')):'<p class="muted">Details have not been supplied yet.</p>'}${key==='locations'&&entry.images?.length?`<div class="photos guide-photos">${entry.images.map(image=>photo(image.src,image.alt,image.title||'',image.detail||'')).join('')}</div>`:''}</section>`;};
  $('#content').innerHTML=`<article class="substance-guide"><header class="guide-intro"><p class="eyebrow">ZEPHYR RP · CITY GUIDE</p><h2>${SUBSTANCE_SECTIONS[substanceSection]}</h2><p class="muted">${Object.values(entry).some(v=>typeof v==='string'&&v.trim())?'Your reference for this activity in the city.':'This guide is ready for your city-specific information.'}</p></header><div class="guide-chapters">${Object.keys(substanceFields).map(section).join('')}</div></article>`;bindPhotos();
}
function renderSubstanceEditor(){
  $('#editor-body').innerHTML=`<p class="editor-help">Write the in-game guide here. For requirements, steps and tips, use one entry per line. Preview, then export guide.json to keep your changes.</p><label class="editor-form">Substance<select id="edit-substance">${Object.entries(SUBSTANCE_SECTIONS).map(([id,name])=>`<option value="${id}" ${id===substanceSection?'selected':''}>${name}</option>`).join('')}</select></label><div id="substance-fields"></div>`;
  const fields=()=>{const id=$('#edit-substance').value,entry=guide.substanceGuides?.[id]||{};$('#substance-fields').innerHTML=`<form id="substance-form" class="editor-form guide-editor">${Object.entries(substanceFields).map(([key,label])=>`<label>${label}<textarea name="${key}">${esc(entry[key]||'')}</textarea></label>`).join('')}<div class="editor-actions"><button class="primary" type="submit">Apply guide to preview</button><button type="button" id="export-substance-guide">Export guide.json</button></div></form>`;
    $('#substance-form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),g=structuredClone(guide);g.substanceGuides??={};g.substanceGuides[id]={...g.substanceGuides[id],...Object.fromEntries(Object.keys(substanceFields).map(key=>[key,form.get(key).trim()]))};applyPreview(g,recipes);editorStatus('Guide applied to preview. Export guide.json to keep these changes.');}catch(error){editorStatus(error.message,true);}};
    $('#export-substance-guide').onclick=()=>download('guide.json',guide);
  };$('#edit-substance').onchange=fields;fields();
}
const status=(message,error=false)=>{$('#status').textContent=message;$('#status').classList.toggle('error',error);};
const recipe=()=>recipes.find(r=>r.id===selectedId);
const duration=seconds=>formatDuration(seconds);
const postalLabel=location=>location.postcodeType==='closest'?'Closest postal':'Postcode';
const itemName=id=>guide.items.find(i=>i.id===id)?.name||id;
const categoryLabels={ammo:'Ammo',weapons:'Weapons',substances:'Substances',attachments:'Attachments',heist:'Heist items',generic:'Generic items',melee:'Melee',smelting:'Smelting',mining:'Mining',business:'Business'};
const categoryIcons={ammo:'M8 20V8l4-5 4 5v12H8ZM8 15h8',weapons:'M4 7h16v6h-7l-2 7H6l2-7H4V7Zm10 0v6',substances:'M9 3h6M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M8 15h8',attachments:'M3 12h18M12 3v18M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0',heist:'M5 7h14v14H5V7Zm4 0V3h6v4M5 12h14M10 12v3h4v-3',generic:'m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v10',melee:'m5 20 4-4M7 14l3 3M9 14 18 3l3 1-2 5-8 7',smelting:'M12 3c1 5 7 7 7 12a7 7 0 0 1-14 0c0-3 2-5 4-7 0 3 1 4 2 4s2-4 1-9Z',mining:'m5 21 12-15M3 7c6-5 12-4 18 2l-2 2C13 6 9 5 3 7Z',locations:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM14 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0'};
function categoryLink(id,name,count){const active=category===id,detail=id==='substances'?'4 guides':id==='locations'?`${count} locations`:count?`${count} recipes`:'Coming soon';return `<a href="#${esc(id)}" class="${active?'active':''} ${count?'':'pending'}" ${active?'aria-current="page"':''} aria-label="${esc(categoryLabels[id]||name)} — ${detail}"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${categoryIcons[id]||categoryIcons.generic}"/></svg></span><span class="nav-label">${esc(categoryLabels[id]||name)}<small>${detail}</small></span></a>`;}
async function load(){try{status('Loading latest guide…');const fetchJson=async file=>{const r=await fetch('data/'+file,{cache:'no-store'});if(!r.ok)throw new Error('Could not load '+file);return r.json();};const g=await fetchJson('guide.json');validateData(g,[]);const groups=await Promise.all(g.categories.map(c=>fetchJson(c.file)));groups.forEach((rows,i)=>{if(!Array.isArray(rows)||rows.some(r=>r.categoryId!==g.categories[i].id))throw new Error('Recipe file does not match its category.');});const all=groups.flat();validateData(g,all);guide=g;recipes=all;plan=[];inventory={};route();status('');}catch(e){status('Guide could not be reloaded: '+e.message+'. Check the data files, then try Reload data.',true);}}
function route(){if(!guide)return;const id=location.hash.slice(1);category=id==='locations'||guide.categories.some(c=>c.id===id)?id:guide.categories[0].id;const choices=recipes.filter(r=>r.categoryId===category);if(!choices.some(r=>r.id===selectedId)){selectedId=choices[0]?.id;quantity=choices[0]?.outputQuantity||1;}render();}
function render(){
  const navigationFocused=$('#navigation').contains(document.activeElement);
  $('#navigation').innerHTML=guide.categories.map(c=>categoryLink(c.id,c.name,recipes.filter(r=>r.categoryId===c.id).length)).join('')+categoryLink('locations','Locations & benches',guide.locations.length);
  // On narrow screens the menu scrolls sideways, so keep the current page in view.
  const nav=$('#navigation'),activeLink=nav.querySelector('.active');if(activeLink&&nav.scrollWidth>nav.clientWidth)nav.scrollLeft=activeLink.offsetLeft-(nav.clientWidth-activeLink.offsetWidth)/2;
  if(navigationFocused)$('#navigation [aria-current="page"]')?.focus({preventScroll:true});
  const c=guide.categories.find(c=>c.id===category);
  renderWeaponTiers();
  renderSubstanceSections();
  $('#page-title').innerHTML=esc(c?c.name:'Locations & benches')+'<span>.</span>';
  $('#breadcrumb').textContent=c?'CRAFTING':'LOCATIONS';
  $('#page-description').textContent=category==='smelting'?'Start with the ore you have. See your yield, fuel requirements and leftovers.':c?'Choose a recipe, prepare your materials, find your bench.':'Know where to go. Find the bench when you get there.';
  if(category==='locations'){renderLocations();return;}
  if(category==='business'){
    $('#page-description').textContent='Enter the parts you need to craft. Get the materials and time for your quota.';
    renderBusiness($('#content'),recipes.filter(r=>r.categoryId==='business'),guide,entries=>{const next=plan.map(e=>({...e}));for(const entry of entries){const existing=next.find(e=>e.recipeId===entry.recipeId);if(existing)existing.quantity+=entry.quantity;else next.push(entry);}next.forEach(e=>calculate(recipes.find(r=>r.id===e.recipeId),e.quantity));plan=next;renderPlan();});renderPlan();return;
  }
  if(category==='substances'){renderSubstanceGuide();return;}
  const rows=recipes.filter(r=>r.categoryId===category&&(category!=='weapons'||r.tier===weaponTier)&&(category!=='substances'||r.substance===substanceSection));
  if(rows.length&&!rows.some(r=>r.id===selectedId)){selectedId=rows[0].id;quantity=rows[0].outputQuantity;}
  if(!rows.length){$('#content').innerHTML=`<div class="empty"><p class="eyebrow">THE GUIDE IS GROWING</p><h2>${esc(c.name)}${category==='weapons'?' · Tier '+weaponTier:category==='substances'?' · '+SUBSTANCE_SECTIONS[substanceSection]:''}</h2><p class="muted">${category==='mining'?'Mining locations, tools and yields have not been supplied yet.':category==='weapons'?'No recipes have been supplied for Tier '+weaponTier+' yet.':category==='substances'?'No recipes have been supplied for '+SUBSTANCE_SECTIONS[substanceSection]+' yet.':'No recipes have been supplied for this section yet.'}<br>Details will appear here as the guide expands.</p></div><div id="plan"></div>`;renderPlan();return;}
  const current=recipe(),bench=guide.benches.find(b=>b.id===current.benchId)||{id:null,name:'Location not supplied',image:'',notes:'Bench details and photos have not been supplied.'},loc=guide.locations.find(l=>l.id===bench.locationId)||{name:'Location pending',postcode:'Not supplied',mapImage:'',notes:'The location and postcode are awaiting details.'};
  $('#content').innerHTML=`<div class="location-strip"><div><strong>⌖ &nbsp;${esc(bench.name)}</strong><div class="muted">${bench.id?rows.filter(r=>r.benchId===bench.id).length+' recipes at this bench · '+esc(loc.name):'Bench and postcode have not been supplied.'}</div></div><span class="tag">${postalLabel(loc).toUpperCase()} ${esc(loc.postcode)}</span><button id="jump-location" class="quiet">View location guide</button></div><div class="work-grid">${recipePicker(rows,current)}<section class="calculator" aria-label="Crafting calculator"><div class="calc-heading"><p class="eyebrow">CRAFTING CALCULATOR</p><h2>${esc(current.name)}</h2><p>Set your target. We’ll round up to full crafts.${current.outputName?' Output: '+esc(current.outputName)+'.':''}</p></div><div class="calc-body"><label for="quantity">How many do you need?</label><div class="quantity-row"><button id="decrement" aria-label="Decrease by one craft">−</button><input id="quantity" type="number" min="1" max="1000000" step="1" value="${quantity}" inputmode="numeric"><button id="increment" aria-label="Increase by one craft">+</button></div><div id="calculation" aria-live="polite"></div><button class="primary" id="add-plan">Add to crafting plan</button><p class="fine">${esc(current.notes||'Recipe supplied by the guide maintainer. Costs are materials per craft.')} Time estimates assume consecutive crafts, excluding travel and gathering.</p></div></section></div><section class="location-section" id="location-guide"><div class="section-header"><div><p class="eyebrow">FIND YOUR WORKBENCH</p><h2>${esc(bench.name)}</h2></div><span class="tag">${postalLabel(loc).toUpperCase()} ${esc(loc.postcode)}</span></div><div class="photos">${photo(loc.mapImage,loc.mapAlt,'01 / Map location',postalLabel(loc)+' '+loc.postcode)}${photo(bench.image,bench.imageAlt,'02 / Bench & surroundings',loc.name)}</div><p class="location-notes">${esc(loc.notes)} ${esc(bench.notes)}</p></section><div id="plan"></div>`;
  $('.calc-body').insertAdjacentHTML('beforeend',`<details class="per-craft"><summary>Original recipe · ${fmt(current.outputQuantity)} per craft</summary><dl class="ingredients">${current.ingredients.map(i=>`<div><dt>${esc(itemName(i.itemId))}</dt><dd>${fmt(i.quantity)}</dd></div>`).join('')}</dl></details>`);
  document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{const next=rows.find(r=>productName(r)===b.dataset.product);selectRecipe(next.id);document.querySelectorAll('[data-product]').forEach(button=>{if(button.dataset.product===productName(recipe()))button.focus();});});
  $('#recipe-variant').onchange=e=>{selectRecipe(e.target.value);$('#recipe-variant').focus();};
  if(category==='smelting')setupAvailableMode();
  $('#quantity').oninput=e=>{quantity=Number(e.target.value);updateCalculation();};
  $('#decrement').onclick=()=>{quantity=Math.max(1,(Number.isSafeInteger(quantity)?quantity:1)-recipe().outputQuantity);$('#quantity').value=quantity;updateCalculation();};
  $('#increment').onclick=()=>{quantity=Math.min(MAX_QUANTITY,(Number.isSafeInteger(quantity)?quantity:0)+recipe().outputQuantity);$('#quantity').value=quantity;updateCalculation();};
  $('#add-plan').onclick=()=>{try{const plannedQuantity=category==='smelting'&&smeltMode==='available'?calculateAvailable(recipe(),availableItemId,availableAmount).output:quantity;calculate(recipe(),plannedQuantity);const found=plan.find(p=>p.recipeId===selectedId);if(found){calculate(recipe(),found.quantity+plannedQuantity);found.quantity+=plannedQuantity;}else plan.push({recipeId:selectedId,quantity:plannedQuantity});renderPlan();status('Added '+recipe().name+' to your crafting plan.');}catch(e){status(e.message,true);}};
  $('#jump-location').onclick=()=>$('#location-guide').scrollIntoView();bindPhotos();updateCalculation();renderPlan();
}
function productName(r){return r.name.split(' (')[0].replace(/ Ingot$/,'');}
function renderLocations(){
  const locations=guide.locations.map(location=>{const benches=guide.benches.filter(b=>b.locationId===location.id);return {location,benches,title:benches.length===1?benches[0].name:location.name};}).sort((a,b)=>a.title.localeCompare(b.title,'en',{numeric:true}));
  $('#page-description').textContent=`${locations.length} locations · Each entry pairs its map with its bench photo. Sorted by name.`;
  $('#content').innerHTML=locations.map(({location:l,benches,title})=>`<section class="location-section location-entry" aria-label="${esc(title)} — ${postalLabel(l).toLowerCase()} ${esc(l.postcode)}"><div class="section-header"><div><p class="eyebrow">CRAFTING LOCATION</p><h2>${esc(title)}</h2></div><span class="tag">${postalLabel(l).toUpperCase()} ${esc(l.postcode)}</span></div><div class="photos">${photo(l.mapImage,l.mapAlt,'Map location',postalLabel(l)+' '+l.postcode)}${benches.map(b=>photo(b.image,b.imageAlt,benches.length===1?'Bench & surroundings':b.name,postalLabel(l)+' '+l.postcode)).join('')}</div><div class="location-entry-footer"><div>${l.notes?`<p class="location-notes">${esc(l.notes)}</p>`:''}${benches.filter(b=>b.notes).map(b=>`<p class="location-notes">${benches.length>1?esc(b.name)+': ':''}${esc(b.notes)}</p>`).join('')}</div><div class="location-entry-actions">${benches.filter(b=>recipes.some(r=>r.benchId===b.id)).map(b=>`<button data-bench="${esc(b.id)}">${benches.length===1?'View recipes':'View '+esc(b.name)+' recipes'}</button>`).join('')}</div></div></section>`).join('')||'<div class="empty">No locations added yet.</div>';
  bindPhotos();
  document.querySelectorAll('[data-bench]').forEach(b=>b.onclick=()=>{const r=recipes.find(r=>r.benchId===b.dataset.bench);selectedId=r.id;quantity=r.outputQuantity;if(r.categoryId==='weapons')weaponTier=r.tier;if(r.categoryId==='substances')substanceSection=r.substance;location.hash=r.categoryId;});
}
function selectRecipe(id){selectedId=id;quantity=recipe().outputQuantity;availableAmount=0;availableItemId='';render();}
function recipePicker(rows,current){
  const products=[...new Set(rows.map(productName))],variants=rows.filter(r=>productName(r)===productName(current));
  return `<section class="catalog recipe-library" aria-label="Recipe selection"><div class="section-header"><div><p class="eyebrow">RECIPE LIBRARY</p><h2>What are you making?</h2></div><span class="muted">${products.length} items · ${rows.length} recipes</span></div><div class="product-strip" role="group" aria-label="Choose an item">${products.map(name=>`<button data-product="${esc(name)}" aria-pressed="${name===productName(current)}">${esc(name)}${rows.filter(r=>productName(r)===name).length>1?` <small>${rows.filter(r=>productName(r)===name).length} methods</small>`:''}</button>`).join('')}</div><div class="method-row"><label for="recipe-variant">Crafting method<select id="recipe-variant">${variants.map(r=>`<option value="${esc(r.id)}" ${r.id===current.id?'selected':''}>${esc(r.name)} — ${esc(r.ingredients.map(i=>itemName(i.itemId)).join(' + '))}</option>`).join('')}</select></label><div class="recipe-facts"><span>Output per craft<strong>${fmt(current.outputQuantity)} ${esc(current.outputName||current.name)}</strong></span><span>Time per craft<strong>${duration(current.craftTimeSeconds)}</strong></span>${current.categoryId==='smelting'&&current.maxCraftsPerRun?`<span>Maximum per run<strong>${fmt(current.maxCraftsPerRun)} smelts</strong></span><span>Longest crafting time<strong>${current.maxRunTimeSeconds?'Approx. '+duration(current.maxRunTimeSeconds):'Not supplied'}</strong></span>`:''}</div></div></section>`;
}
function setupAvailableMode(){
  const r=recipe();
  if(!r.ingredients.some(i=>i.itemId===availableItemId))availableItemId=(r.ingredients.find(i=>i.itemId!=='coal-ore')||r.ingredients[0]).itemId;
  $('.calc-heading p:last-child').textContent=smeltMode==='available'?'Turn the materials you have into a smelting plan.':'Choose your desired output. Materials round up to full crafts.';
  $('.calc-heading').insertAdjacentHTML('beforeend',`<div class="mode-switch" role="group" aria-label="Smelting calculation mode"><button data-mode="available" aria-pressed="${smeltMode==='available'}">Ore / item available</button><button data-mode="target" aria-pressed="${smeltMode==='target'}">Target output</button></div>`);
  document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{smeltMode=b.dataset.mode;render();document.querySelector(`[data-mode="${smeltMode}"]`).focus();});
  if(smeltMode!=='available')return;
  $('.calc-body').classList.add('available-mode');
  $('label[for="quantity"]').hidden=true;$('.quantity-row').hidden=true;
  $('.calc-body').insertAdjacentHTML('afterbegin',`<div class="available-controls"><label for="available-item">Ore or item you have</label><select id="available-item">${r.ingredients.map(i=>`<option value="${esc(i.itemId)}" ${i.itemId===availableItemId?'selected':''}>${esc(itemName(i.itemId))}</option>`).join('')}</select><label for="available-quantity">Amount available</label><input id="available-quantity" type="number" min="0" max="1000000" step="1" inputmode="numeric" value="${availableAmount}" aria-describedby="available-help"><p class="fine" id="available-help">Full crafts only. Other ingredients are requirements, not limits. Choose any ingredient to calculate from it.</p></div>`);
  $('#available-item').onchange=e=>{availableItemId=e.target.value;availableAmount=0;$('#available-quantity').value=0;updateCalculation();};
  $('#available-quantity').oninput=e=>{availableAmount=e.target.value===''?NaN:Number(e.target.value);updateCalculation();};
}
function updateAvailable(){
  try{
    const r=calculateAvailable(recipe(),availableItemId,availableAmount),coal=r.materials.find(i=>i.itemId==='coal-ore');
    $('#available-quantity').removeAttribute('aria-invalid');
    $('#calculation').innerHTML=`<div class="smelt-result"><p class="eyebrow">MAXIMUM OUTPUT</p><strong>${fmt(r.output)}</strong><span>${esc(recipe().outputName||recipe().name)}</span></div><div class="batch-summary"><div><strong>${fmt(r.batches)}</strong>full crafts</div><div><strong>${fmt(r.used)}</strong>${esc(itemName(r.itemId))} used</div><div><strong>${fmt(r.leftover)}</strong>left over</div></div>${coal?`<div class="coal-required"><span>Coal Ore required</span><strong>${fmt(coal.quantity)}</strong></div>`:'<p class="fine">This recipe does not use Coal Ore.</p>'}<div class="totals"><p class="eyebrow">ALL MATERIALS REQUIRED</p>${r.materials.map(i=>`<div class="total-row"><span>${esc(itemName(i.itemId))}</span><b>${fmt(i.quantity)}</b></div>`).join('')}</div><div class="total-row"><span>Total craft time</span><b>${duration(r.totalTimeSeconds)}</b></div>${r.batches===0?`<p class="fine">One craft needs ${fmt(recipe().ingredients.find(i=>i.itemId===availableItemId).quantity)} ${esc(itemName(availableItemId))}.</p>`:''}${r.output>MAX_QUANTITY?'<p class="fine">This output exceeds the plan limit of 1,000,000. Use a smaller amount to add it to your plan.</p>':''}`;
    $('#add-plan').disabled=r.output===0||r.output>MAX_QUANTITY;
    $('#add-plan').textContent='Add smelting output to plan';
  }catch(e){$('#available-quantity').setAttribute('aria-invalid','true');$('#calculation').innerHTML=`<p class="error">${esc(e.message)}</p>`;$('#add-plan').disabled=true;}
}
function photo(src,alt,title,detail){return `<div class="photo-slot">${src?`<button data-photo="${esc(src)}" data-alt="${esc(alt||title)}" aria-label="Enlarge ${esc(title)}"><img src="${esc(src)}" alt="${esc(alt||title)}" loading="lazy"></button>`:`<div class="photo-placeholder"><span>⌖</span><p>${title.includes('Map')?'Map image':'Bench photo'} awaiting upload</p></div>`}<div class="photo-caption"><span>${esc(title)}</span><small>${esc(detail)}</small></div></div>`;}
function bindPhotos(){document.querySelectorAll('[data-photo]').forEach(b=>{b.onclick=()=>{$('#large-photo').src=b.dataset.photo;$('#large-photo').alt=b.dataset.alt;$('#photo-caption').textContent=b.dataset.alt;$('#photo-dialog').showModal();};b.querySelector('img').onerror=()=>{b.disabled=true;b.innerHTML='<div class="photo-placeholder"><p>Image unavailable. Update the image path.</p></div>';};});}
function updateCalculation(){if(category==='smelting'&&smeltMode==='available'){updateAvailable();return;}try{const r=calculate(recipe(),quantity);$('#quantity').removeAttribute('aria-invalid');$('#calculation').innerHTML=`<div class="batch-summary"><div><strong>${fmt(r.batches)}</strong>craft${r.batches===1?'':'s'}</div><div><strong>${fmt(r.output)}</strong>total output</div><div><strong>${fmt(r.surplus)}</strong>extra</div></div><div class="craft-time"><p class="eyebrow">TIME TO CRAFT</p><div class="total-row"><span>Per craft</span><b>${duration(recipe().craftTimeSeconds)}</b></div><div class="total-row"><span>${r.totalTimeSeconds===null?'Total time':'Total for '+fmt(r.batches)+(r.batches===1?' craft':' crafts')}</span><b>${duration(r.totalTimeSeconds)}</b></div></div><div class="totals"><p class="eyebrow" >MATERIALS REQUIRED</p>${r.materials.map(i=>`<div class="total-row"><span>${esc(itemName(i.itemId))}</span><b>${fmt(i.quantity)}</b></div>`).join('')}</div>`;$('#add-plan').disabled=false;}catch(e){$('#quantity').setAttribute('aria-invalid','true');$('#calculation').innerHTML=`<p class="fine">${esc(e.message)}</p>`;$('#add-plan').disabled=true;}}
function renderPlan(){if(!$('#plan'))return;const totals=combinePlan(recipes,plan,inventory),timing=planDuration(recipes,plan);$('#plan').innerHTML=`<section class="plan"><div class="section-header"><h2>Your crafting plan</h2><span class="muted">This session only</span></div>${!plan.length?'<p class="muted">Add recipes to combine their materials into one preparation list.</p>':`<ul>${plan.map(p=>{const r=recipes.find(r=>r.id===p.recipeId),calc=calculate(r,p.quantity);return `<li><div>${esc(r.name)} <small>${fmt(p.quantity)} requested · ${fmt(calc.batches)} crafts · ${fmt(calc.output)} output · ${duration(calc.totalTimeSeconds)}${calc.totalTimeSeconds===null?' (time pending)':' crafting'}</small></div><button data-remove="${esc(p.recipeId)}" aria-label="Remove ${esc(r.name)} from plan">Remove</button></li>`;}).join('')}</ul><div class="plan-time"><strong>${timing.unknownRecipes?'Total time incomplete':'Total crafting time: '+duration(timing.totalSeconds)}</strong><p class="fine">${timing.unknownRecipes?duration(timing.knownSeconds)+' known; '+timing.unknownRecipes+' recipe(s) still need a duration. ':''}Consecutive crafts only; travel and gathering excluded.</p></div><table><thead><tr><th>Material</th><th>Required</th><th>You have</th><th>Still need</th></tr></thead><tbody>${totals.map(t=>`<tr><td>${esc(itemName(t.itemId))}</td><td>${fmt(t.quantity)}</td><td><input type="number" min="0" max="1000000000000" step="1" data-owned="${esc(t.itemId)}" aria-label="${esc(itemName(t.itemId))} already owned" value="${t.owned}"></td><td data-missing="${esc(t.itemId)}">${fmt(t.missing)}</td></tr>`).join('')}</tbody></table><p class="fine">Repeated requests for the same recipe are combined before rounding to full crafts. Inventory reduces the shopping list, not the number of crafts.</p><button id="copy-plan">Copy materials list</button><p id="plan-status" role="status" class="fine"></p>`}</section>`;
  document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{plan=plan.filter(p=>p.recipeId!==b.dataset.remove);renderPlan();});
  document.querySelectorAll('[data-owned]').forEach(input=>input.oninput=()=>{const n=Number(input.value);if(!Number.isSafeInteger(n)||n<0||n>1e12||input.value===''){input.setAttribute('aria-invalid','true');$('#plan-status').textContent='Owned quantities must be whole numbers from 0 to 1,000,000,000,000.';$('#copy-plan').disabled=true;return;}input.removeAttribute('aria-invalid');inventory[input.dataset.owned]=n;const t=totals.find(t=>t.itemId===input.dataset.owned);document.querySelector(`[data-missing="${input.dataset.owned}"]`).textContent=fmt(Math.max(0,t.quantity-n));$('#copy-plan').disabled=!!document.querySelector('[data-owned][aria-invalid]');$('#plan-status').textContent=$('#copy-plan').disabled?'Correct the highlighted inventory quantities.':'';});
  if($('#copy-plan'))$('#copy-plan').onclick=async()=>{try{const text='ZEPHYR RP — Crafting plan\n'+plan.map(p=>{const r=recipes.find(r=>r.id===p.recipeId);return `${r.name}: ${p.quantity} requested (${calculate(r,p.quantity).batches} crafts; time: ${duration(calculate(r,p.quantity).totalTimeSeconds)})`;}).join('\n')+'\n'+(timing.unknownRecipes?'Time incomplete: '+duration(timing.knownSeconds)+' known; '+timing.unknownRecipes+' recipe(s) missing duration.':'Total crafting time: '+duration(timing.totalSeconds))+'\n\n'+combinePlan(recipes,plan,inventory).map(t=>`${itemName(t.itemId)}: ${t.quantity} required / ${t.owned} owned / ${t.missing} needed`).join('\n');await navigator.clipboard.writeText(text);$('#plan-status').textContent='Materials list copied.';}catch{$('#plan-status').textContent='Clipboard access is unavailable. You can select and copy the table manually.';}};
}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
$('#reload').onclick=()=>{if(confirm('Reload published data? This clears your current plan and any unexported editor preview.'))load();};
window.addEventListener('hashchange',route);
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#manage').onclick=()=>{if(!guide)return;renderEditor();$('#manager').showModal();};
function editorStatus(message,error=false){$('#editor-status').textContent=message;$('#editor-status').classList.toggle('error',error);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);editorStatus('Exported '+name+'. Replace dist/data/'+name+' and republish to update the shared guide.');}
function applyPreview(g,r){validateData(g,r);guide=g;recipes=r;plan=plan.filter(p=>recipes.some(r=>r.id===p.recipeId));route();status('Viewing an editor preview. Export your changes before reloading.');}
function renderEditor(){
  $('#editor-content').innerHTML=`<div class="editor-tabs">${[['photos','Location photos'],['substance-guides','Substance guides'],['recipes','Recipe editor'],['json','Advanced data']].map(([id,name])=>`<button data-editor="${id}" class="${id===editorTab?'active':''}">${name}</button>`).join('')}</div><div id="editor-body"></div>`;
  document.querySelectorAll('[data-editor]').forEach(b=>b.onclick=()=>{editorTab=b.dataset.editor;editorStatus('');renderEditor();});
  if(editorTab==='photos')renderPhotoEditor();else if(editorTab==='substance-guides')renderSubstanceEditor();else if(editorTab==='recipes')renderRecipeEditor();else renderJsonEditor();
}
function renderPhotoEditor(){
  $('#editor-body').innerHTML=`<p class="editor-help">Each location has a map image; each bench has its own surroundings photo. Use a hosted HTTPS image URL, or a path such as images/mainland-938-map.webp. Empty fields show “awaiting upload”.</p><label class="editor-form">Choose a bench<select id="edit-bench">${guide.benches.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><div id="photo-fields"></div>`;
  const fields=()=>{const b=guide.benches.find(b=>b.id===$('#edit-bench').value);if(!b){$('#photo-fields').textContent='Add a location and bench in Advanced data first.';return;}const l=guide.locations.find(l=>l.id===b.locationId);$('#photo-fields').innerHTML=`<form id="photo-form" class="editor-form"><div class="editor-fields"><label>Location name<input name="locationName" required value="${esc(l.name)}"></label><label>Postcode<input name="postcode" required value="${esc(l.postcode)}"></label><label>Map image URL or path<input name="mapImage" value="${esc(l.mapImage)}" placeholder="images/mainland-938-map.webp"></label><label>Map image description<input name="mapAlt" value="${esc(l.mapAlt)}"></label><label>Bench image URL or path<input name="image" value="${esc(b.image)}" placeholder="images/mainland-ammo-bench.webp"></label><label>Bench image description<input name="imageAlt" value="${esc(b.imageAlt)}"></label><label>Location directions / notes<input name="locationNotes" value="${esc(l.notes)}"></label><label>Bench directions / notes<input name="benchNotes" value="${esc(b.notes)}"></label></div><div class="editor-actions"><button class="primary" type="submit">Apply photo details to preview</button><button id="export-guide" type="button">Export guide.json</button></div></form>`;
    $('#photo-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),g=structuredClone(guide),loc=g.locations.find(x=>x.id===l.id),bench=g.benches.find(x=>x.id===b.id);Object.assign(loc,{name:f.get('locationName').trim(),postcode:f.get('postcode').trim(),mapImage:f.get('mapImage').trim(),mapAlt:f.get('mapAlt'),notes:f.get('locationNotes')});Object.assign(bench,{image:f.get('image').trim(),imageAlt:f.get('imageAlt'),notes:f.get('benchNotes')});applyPreview(g,recipes);editorStatus('Photo details applied to this preview. Export guide.json to keep them.');}catch(err){editorStatus(err.message,true);}};$('#export-guide').onclick=()=>download('guide.json',guide);};
  const showFields=()=>{fields();const b=guide.benches.find(b=>b.id===$('#edit-bench').value);if(b){$('#photo-fields').insertAdjacentHTML('afterbegin',imageInstructions(b));}};
  $('#edit-bench').onchange=showFields;showFields();
}
function imageInstructions(bench){
  const loc=guide.locations.find(l=>l.id===bench.locationId),mapName=loc.mapImage?.startsWith('images/')?loc.mapImage.slice(7):loc.id+'-map.webp',benchName=bench.image?.startsWith('images/')?bench.image.slice(7):bench.id+'-bench.webp';
  return `<details class="image-help" open><summary>Where to put images for ${esc(bench.name)}</summary><p>Save both screenshots in your project’s <code>zephyr-guide/dist/images/</code> folder.</p><table><thead><tr><th>Guide position</th><th>Filename & matching field value</th></tr></thead><tbody><tr><td>Map location<br><small>${postalLabel(loc)} ${esc(loc.postcode)}</small></td><td><code>${esc(mapName)}</code><br>Map image field: <code>images/${esc(mapName)}</code></td></tr><tr><td>Bench & surroundings</td><td><code>${esc(benchName)}</code><br>Bench image field: <code>images/${esc(benchName)}</code></td></tr></tbody></table><ol><li>Save the images using these names, or your own descriptive filenames. PNG, JPG, JPEG, WebP and GIF work. Use the actual file extension in the field; renaming a PNG to WebP does not convert it.</li><li>Enter the matching paths in the form below. The <strong>field assigns the position</strong>; the filename alone does not. Paths start with <code>images/</code>, not <code>dist/images/</code>.</li><li>Apply to preview, export <code>guide.json</code>, and replace <code>zephyr-guide/dist/data/guide.json</code> with the exported file.</li><li>Republish the images and JSON together. Files saved only on your PC are not uploaded by this form and will not appear on the hosted site until published.</li></ol><p>For replacements, use a new filename such as <code>${esc(loc.id)}-map-v2.webp</code> and update its field to avoid cached images. Landscape screenshots around 1600 × 900 work well. The full image is shown without cropping; click it to enlarge.</p></details>`;
}
function renderRecipeEditor(){
  $('#editor-body').innerHTML=`<label class="editor-form">Recipe<select id="edit-recipe"><option value="new">Add a new recipe</option>${recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></label><div id="recipe-fields"></div>`;
  if(recipe())$('#edit-recipe').value=selectedId;
  const fields=()=>{const existing=recipes.find(r=>r.id===$('#edit-recipe').value),r=existing||{id:'',name:'',categoryId:guide.categories[0].id,benchId:null,outputQuantity:1,ingredients:[],notes:''};$('#recipe-fields').innerHTML=`<form id="recipe-form" class="editor-form"><div class="editor-fields"><label>Stable recipe ID<input name="id" required pattern="[a-z0-9-]+" ${existing?'readonly':''} value="${esc(r.id)}" placeholder="ammo-example"></label><label>Recipe name<input name="name" required value="${esc(r.name)}"></label><label>Category<select name="categoryId">${guide.categories.filter(c=>c.id!=='substances').map(c=>`<option value="${esc(c.id)}" ${c.id===r.categoryId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label id="weapon-tier-field">Weapon tier<select name="tier">${[1,2,3].map(t=>`<option value="${t}" ${t===(r.tier||3)?'selected':''}>Tier ${t}</option>`).join('')}</select></label><label id="substance-section-field">Substance section<select name="substance">${Object.entries(SUBSTANCE_SECTIONS).map(([id,name])=>`<option value="${id}" ${id===(r.substance||'meth')?'selected':''}>${name}</option>`).join('')}</select></label><label>Bench<select name="benchId"><option value="" ${r.benchId===null?'selected':''}>Location not supplied</option>${guide.benches.map(b=>`<option value="${esc(b.id)}" ${b.id===r.benchId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label>Output per craft<input name="outputQuantity" type="number" required min="1" max="1000000" step="1" value="${r.outputQuantity}"></label><label>Time per craft (seconds)<input name="craftTimeSeconds" type="number" required min="1" max="86400" step="1" value="${r.craftTimeSeconds??''}" placeholder="Required, e.g. 30"></label><label>Output item name<input name="outputName" value="${esc(r.outputName||'')}" placeholder="Optional, e.g. Copper Ingot"></label><label>Notes / requirements<input name="notes" value="${esc(r.notes)}"></label></div><h3>Ingredients per craft</h3><p class="editor-help">Set unused ingredients to 0. Add new material types in Advanced data → guide.json.</p><div class="editor-fields">${guide.items.map(i=>`<label>${esc(i.name)}<input type="number" name="ingredient:${esc(i.id)}" min="0" max="1000000" step="1" required value="${r.ingredients.find(x=>x.itemId===i.id)?.quantity||0}"></label>`).join('')}</div><div class="editor-actions"><button type="submit" class="primary">Apply recipe to preview</button><button type="button" id="export-recipes">Export category JSON</button></div></form>`;
    const syncTier=()=>{const isWeapon=$('#recipe-form [name=categoryId]').value==='weapons';$('#weapon-tier-field').hidden=!isWeapon;$('#recipe-form [name=tier]').disabled=!isWeapon;const isSubstance=$('#recipe-form [name=categoryId]').value==='substances';$('#substance-section-field').hidden=!isSubstance;$('#recipe-form [name=substance]').disabled=!isSubstance;};$('#recipe-form [name=categoryId]').onchange=syncTier;syncTier();
    $('#recipe-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),next={...r,id:f.get('id').trim(),name:f.get('name').trim(),categoryId:f.get('categoryId'),benchId:f.get('benchId')||null,outputQuantity:Number(f.get('outputQuantity')),craftTimeSeconds:Number(f.get('craftTimeSeconds')),outputName:f.get('outputName').trim(),notes:f.get('notes'),source:r.source||'Supplied by guide maintainer',ingredients:guide.items.map(i=>({itemId:i.id,quantity:Number(f.get('ingredient:'+i.id))})).filter(i=>i.quantity!==0)};if(next.categoryId==='weapons')next.tier=Number(f.get('tier'));else delete next.tier;if(next.categoryId==='substances')next.substance=f.get('substance');else delete next.substance;const updated=existing?recipes.map(x=>x.id===existing.id?next:x):[...recipes,next];validateData(guide,updated);applyPreview(guide,updated);const moved=existing&&existing.categoryId!==next.categoryId;renderRecipeEditor();$('#edit-recipe').value=next.id;$('#edit-recipe').dispatchEvent(new Event('change'));editorStatus(moved?'Recipe moved in preview. Export both its old and new category files from Advanced data.':'Recipe applied to preview. Export the category JSON to keep this change.');}catch(err){editorStatus(err.message,true);}};
    $('#export-recipes').onclick=()=>{const id=$('#recipe-form [name=categoryId]').value,c=guide.categories.find(c=>c.id===id);download(c.file,recipes.filter(r=>r.categoryId===id));};};
  $('#edit-recipe').onchange=fields;fields();
}
function renderJsonEditor(){
  $('#editor-body').innerHTML=`<p class="editor-help">Edit locations, benches, materials, or recipes as plain JSON. Create new locations and benches in guide.json, then assign recipes to their IDs. Importing replaces only the selected file in this preview.</p><div class="editor-form"><label>Data file<select id="json-file"><option value="guide.json">guide.json — locations, benches & materials</option>${guide.categories.map(c=>`<option value="${esc(c.file)}">${esc(c.file)}</option>`).join('')}</select></label><label>JSON content<textarea id="json-source" spellcheck="false"></textarea></label><label class="editor-file">Load a JSON file<input type="file" id="json-import" accept=".json,application/json"></label><div class="editor-actions"><button class="primary" id="apply-json">Validate & apply to preview</button><button id="export-json">Export JSON content</button></div></div>`;
  const populate=()=>{const file=$('#json-file').value,c=guide.categories.find(c=>c.file===file);$('#json-source').value=JSON.stringify(c?recipes.filter(r=>r.categoryId===c.id):guide,null,2);};$('#json-file').onchange=populate;populate();
  const read=()=>{const value=JSON.parse($('#json-source').value),file=$('#json-file').value,c=guide.categories.find(c=>c.file===file);if(c){if(!Array.isArray(value)||value.some(r=>r.categoryId!==c.id))throw new Error('Every recipe in this file must use categoryId '+c.id);validateData(guide,[...recipes.filter(r=>r.categoryId!==c.id),...value]);}else validateData(value,recipes);return {value,file,c};};
  $('#json-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('JSON files must be smaller than 2 MB.');const data=JSON.parse(await file.text());$('#json-source').value=JSON.stringify(data,null,2);editorStatus('Loaded into the editor. Validate & apply to preview when ready.');}catch(err){editorStatus(err.message,true);}};
  $('#apply-json').onclick=()=>{try{const {value,c}=read();if(c)applyPreview(guide,[...recipes.filter(r=>r.categoryId!==c.id),...value]);else applyPreview(value,recipes);editorStatus('Valid data applied to preview. Export the file to keep your changes.');}catch(err){editorStatus(err.message,true);}};
  $('#export-json').onclick=()=>{try{const {file,value}=read();download(file,value);}catch(err){editorStatus(err.message,true);}};
}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_crafting_calculator',description:'Select a guide recipe and set its desired output quantity in the visible calculator. Does not add it to a plan or save guide data.',inputSchema:{type:'object',properties:{recipeId:{type:'string'},quantity:{type:'integer',minimum:1,maximum:MAX_QUANTITY}},required:['recipeId','quantity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.recipeId!=='string')throw new Error('Recipe ID is required.');const r=recipes.find(r=>r.id===input.recipeId);if(!r)throw new Error('Recipe not found.');const result=calculate(r,input.quantity);selectedId=r.id;quantity=input.quantity;category=r.categoryId;if(category==='business')configureBusiness(r.id,input.quantity);if(category==='weapons')weaponTier=r.tier;if(category==='substances')substanceSection=r.substance;smeltMode='target';history.replaceState(null,'','#'+category);render();return {recipe:r.name,...result};}})).catch(()=>{});}catch{}}
load();


